    qty=sum(q for _,q in reqs[case['case_id']])
    found=None
    for room in allowed_rooms(case):
        first=max(int(case['release_min']), math.ceil(float(room['open_min'])/5)*5)
        first=((first+4)//5)*5
        for route in routes_by_room[room['room_id']]:
            if not route_allowed(case, route): continue
            for start in range(first, int(case['latest_start_min'])+1, 5):
                if start+int(case['duration_min'])>float(room['close_min']): continue
                e,l=dep_bounds(start, route)
                dep=math.floor(l)
                if dep<e: continue
                if dep<0:
                    if 0>l: continue
                    dep=0
                if dep_ok(dep, route, qty):
                    found=(room['room_id'], route['route_id'], start, dep, qty)
                    break
            if found: break
        if found: break
    if found:
        wits.append((case['case_id'],)+found)
print('count',len(wits))
for w in wits:
    print(','.join(map(str,w)))
